#include <iostream>
#include <vector>
#include <cstring>
#include <climits>
#include <fstream>

using namespace std;

constexpr int maxN = 50;
constexpr int maxM = 50;
constexpr int maxK = 50;
constexpr int T_val = maxN + maxK + 1;
constexpr int maxN_nodes = maxN * T_val + 1;
constexpr int maxM_edges = maxK + (maxM * 2 * maxK + maxN) * (T_val - 1);
constexpr int INF_DIST = 0x3f3f3f3f;

struct AdjacencyNode {
	AdjacencyNode* next_ptr;
	int target_node;
};

AdjacencyNode node_array[maxN], node_array2[maxN_nodes];
AdjacencyNode* buffer_pool_1 = nullptr;
AdjacencyNode* buffer_pool_2 = nullptr;

int potential_arr[maxN_nodes];
int layer_dist[maxN_nodes];
int parent_edge[maxN_nodes];
int heap_arr[maxN_nodes + 2];
int heap_pos[maxN_nodes];
int heap_elem_count;

inline bool heap_lessthan(int node_a, int node_b) {
	return potential_arr[node_a] < potential_arr[node_b] || 
		(potential_arr[node_a] == potential_arr[node_b] && layer_dist[node_a] < layer_dist[node_b]);
}

int heap_getchild(int index) {
	index *= 2;
	if (index > heap_elem_count) return 0;
	if (index < heap_elem_count && heap_lessthan(heap_arr[index+1], heap_arr[index])) return index+1;
	return index;
}

void heap_moveup(int node_val) {
	int idx = heap_pos[node_val];
	int parent_idx;
	while ((parent_idx = idx / 2) && heap_lessthan(node_val, heap_arr[parent_idx])) {
		heap_arr[heap_pos[heap_arr[parent_idx]] = idx] = heap_arr[parent_idx];
		idx = parent_idx;
	}
	heap_arr[heap_pos[node_val] = idx] = node_val;
}

void heap_movedown(int node_val) {
	int idx = heap_pos[node_val];
	int child_idx;
	while ((child_idx = heap_getchild(idx)) && heap_lessthan(heap_arr[child_idx], node_val)) {
		heap_arr[heap_pos[heap_arr[child_idx]] = idx] = heap_arr[child_idx];
		idx = child_idx;
	}
	heap_arr[heap_pos[node_val] = idx] = node_val;
}

void heap_enqueue(int node_val) {
	heap_pos[node_val] = ++heap_elem_count;
	heap_moveup(node_val);
}

int heap_dequeue() {
	int result = heap_arr[1];
	int last_node = heap_arr[heap_elem_count--];
	heap_pos[last_node] = 1;
	heap_movedown(last_node);
	return result;
}

void extend_adjacency(int source_node, int dest_node) {
	if (!buffer_pool_1) {
		buffer_pool_1 = new AdjacencyNode[maxM * 2 + 1];
		buffer_pool_1--;
	}
	buffer_pool_1->target_node = dest_node;
	buffer_pool_1->next_ptr = node_array[source_node].next_ptr;
	node_array[source_node].next_ptr = buffer_pool_1++;
}

void extend_secondary_graph(int vertex, int edge_index) {
	if (!buffer_pool_2) {
		buffer_pool_2 = new AdjacencyNode[maxM_edges * 2 + 1];
		buffer_pool_2--;
	}
	buffer_pool_2->target_node = edge_index;
	buffer_pool_2->next_ptr = node_array2[vertex].next_ptr;
	node_array2[vertex].next_ptr = buffer_pool_2++;
}

int node_count, edge_count;
int edge_from[maxM_edges];
int edge_to[maxM_edges];
int edge_xor[maxM_edges];
int edge_cost[maxM_edges];
int edge_cost_reduced[maxM_edges];
int edge_capacity[maxM_edges * 2];

void add_edge(int node_u, int node_v, int capacity_val, int cost_val) {
	int idx = edge_count++;
	edge_from[idx] = node_u;
	edge_to[idx] = node_v;
	edge_xor[idx] = node_u ^ node_v;
	edge_cost[idx] = cost_val;
	edge_capacity[idx * 2] = capacity_val;
	extend_secondary_graph(node_u, idx * 2);
	extend_secondary_graph(node_v, idx * 2 + 1);
}

void dijkstra_shortestpath(int source_vertex) {
	memset(potential_arr, 0x3f, sizeof(potential_arr));
	potential_arr[source_vertex] = 0;
	heap_enqueue(source_vertex);
	while (heap_elem_count) {
		AdjacencyNode* iter;
		int curr_node = heap_dequeue();
		int neighbor_node;
		int edge_idx, edge_idx_temp;
		int cost_estimate;
		int new_layer = layer_dist[curr_node] + 1;

		for (iter = node_array2[curr_node].next_ptr; iter; iter = iter->next_ptr) {
			edge_idx_temp = iter->target_node;
			if (edge_capacity[edge_idx_temp]) {
				edge_idx = edge_idx_temp >> 1;
				cost_estimate = potential_arr[curr_node] + ((edge_idx_temp & 1) == 0 ? 
					edge_cost_reduced[edge_idx] : -edge_cost_reduced[edge_idx]);
				neighbor_node = curr_node ^ edge_xor[edge_idx];
				if (potential_arr[neighbor_node] == INF_DIST) {
					potential_arr[neighbor_node] = cost_estimate;
					layer_dist[neighbor_node] = new_layer;
					parent_edge[neighbor_node] = edge_idx_temp;
					heap_enqueue(neighbor_node);
				} else if (potential_arr[neighbor_node] > cost_estimate || 
					(potential_arr[neighbor_node] == cost_estimate && layer_dist[neighbor_node] > new_layer)) {
					potential_arr[neighbor_node] = cost_estimate;
					layer_dist[neighbor_node] = new_layer;
					parent_edge[neighbor_node] = edge_idx_temp;
					heap_moveup(neighbor_node);
				}
			}
		}
	}
}

void augment_flow(int source_node, int sink_node) {
	int curr, idx, idx_temp;
	for (curr = sink_node; curr != source_node; curr ^= edge_xor[idx]) {
		idx = (idx_temp = parent_edge[curr]) >> 1;
		edge_capacity[idx_temp]--;
		edge_capacity[idx_temp ^ 1]++;
	}
}

int min_cost_maxflow(int source_vertex, int sink_vertex) {
	int total_flow_cost = 0, idx;
	memcpy(edge_cost_reduced, edge_cost, sizeof(edge_cost));
	while (true) {
		dijkstra_shortestpath(source_vertex);
		if (potential_arr[sink_vertex] == INF_DIST) break;
		augment_flow(source_vertex, sink_vertex);
		for (idx = 0; idx < edge_count; idx++) {
			int u = edge_from[idx];
			int v = edge_to[idx];
			if (potential_arr[u] != INF_DIST && potential_arr[v] != INF_DIST)
				edge_cost_reduced[idx] += potential_arr[u] - potential_arr[v];
		}
	}
	total_flow_cost = 0;
	for (idx = 0; idx < edge_count; idx++)
		total_flow_cost += edge_cost[idx] * edge_capacity[idx * 2 + 1];
	return total_flow_cost;
}

int main() {
	vector<int> start_nodes(maxK);
	int n, m, k, c, d, t, h, i, j, s, u, v, x;
	cin >> n >> m >> k >> c >> d;
	for (h = 0; h < k; h++) {
		cin >> start_nodes[h];
		start_nodes[h]--;
	}
	while (m--) {
		cin >> i >> j;
		i--; j--;
		extend_adjacency(i, j);
		extend_adjacency(j, i);
	}
	t = n + k + 1;
	node_count = n * t + 1;
	edge_count = 0;
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			AdjacencyNode* iter;
			u = i * t + s;
			for (iter = node_array[i].next_ptr; iter; iter = iter->next_ptr) {
				j = iter->target_node;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					add_edge(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			u = i * t + s;
			v = u + 1;
			add_edge(u, v, k, i == 0 ? 0 : c);
		}
	}
	for (h = 0; h < k; h++)
		add_edge(node_count - 1, start_nodes[h] * t + 0, 1, 0);
	cout << min_cost_maxflow(node_count - 1, 0 * t + t - 1) << endl;
	return 0;
}
